WITH original AS (SELECT * FROM retained), requests AS (SELECT * FROM (VALUES ('correct-date', 'nrr', CAST('2026-07-31' AS DATE), 'original'), ('wrong-grain', 'nrr', CAST('2026-07-01' AS DATE), 'original'), ('other-month', 'nrr', CAST('2026-06-01' AS DATE), 'original'), ('arbitrary-day', 'nrr', CAST('2026-07-30' AS DATE), 'original'), ('unsupported', 'token_yield', CAST('2026-07-01' AS DATE), 'original'), ('empty', 'nrr', CAST('2026-07-01' AS DATE), 'empty'), ('missing-lens', 'nrr', CAST('2026-07-01' AS DATE), 'missing_lens'), ('duplicate-lens', 'nrr', CAST('2026-07-01' AS DATE), 'duplicate_lens'), ('ambiguous-dates', 'nrr', CAST('2026-07-01' AS DATE), 'multiple_dates'), ('unavailable', 'nrr', CAST('2026-07-31' AS DATE), 'unavailable'), ('wrong-grain-unavailable', 'nrr', CAST('2026-07-01' AS DATE), 'unavailable')) AS params("case_id", "population", "requested_date", "scenario")), report_rows AS (SELECT q.case_id, r.month, r.lens, CASE WHEN q.scenario = 'unavailable' THEN 'undefined_zero_base' ELSE r.status END AS status, CASE WHEN q.scenario = 'unavailable' THEN NULL ELSE r.nrr END AS nrr FROM requests AS q CROSS JOIN original AS r WHERE q.scenario <> 'empty' AND (q.scenario <> 'missing_lens' OR r.lens <> 'base_t12m') UNION ALL SELECT q.case_id, r.month, r.lens, r.status, r.nrr FROM requests AS q CROSS JOIN original AS r WHERE q.scenario = 'duplicate_lens' AND r.lens = 'base_t12m' UNION ALL SELECT q.case_id, CAST(r.month - INTERVAL '31' DAYS AS DATE), r.lens, r.status, r.nrr FROM requests AS q CROSS JOIN original AS r WHERE q.scenario = 'multiple_dates'), inspected AS (SELECT q.case_id, q.population, q.requested_date, COUNT(r.case_id) AS population_rows, COUNT(DISTINCT r.month) AS reporting_dates, MIN(r.month) AS reporting_date, COUNT(DISTINCT CASE WHEN r.lens IN ('base_t12m', 'floor_100k', 'subscription_inclusive', 't3m_annualized') THEN r.lens END) AS registered_lenses, CAST(SUM(CASE WHEN r.month = q.requested_date THEN 1 ELSE 0 END) AS BIGINT) AS selected_rows, CAST(SUM(CASE WHEN NOT r.case_id IS NULL AND (r.status <> 'defined' OR r.nrr IS NULL) THEN 1 ELSE 0 END) AS BIGINT) AS unavailable_rows FROM requests AS q LEFT JOIN report_rows AS r ON r.case_id = q.case_id GROUP BY q.case_id, q.population, q.requested_date), classified AS (SELECT *, CASE WHEN population <> 'nrr' THEN 'unsupported_population' WHEN population_rows = 0 THEN 'no_population' WHEN reporting_dates <> 1 THEN 'ambiguous_population' WHEN population_rows <> 4 OR registered_lenses <> 4 THEN 'incomplete_population' WHEN selected_rows > 0 AND unavailable_rows > 0 THEN 'selected_unavailable' WHEN selected_rows > 0 THEN 'selected' WHEN requested_date = CAST(DATE_TRUNC('MONTH', reporting_date) AS DATE) THEN 'date_grain_mismatch' ELSE 'no_matching_date' END AS status FROM inspected), diagnostic AS (SELECT case_id, status, CASE WHEN status = 'date_grain_mismatch' THEN CAST(reporting_date AS TEXT) END AS suggested_date, population_rows, selected_rows, unavailable_rows FROM classified ORDER BY case_id) SELECT * FROM diagnostic ORDER BY case_id